1	/**
2	 * Nexus sidecar protocol v1: newline-delimited JSON between the Ratatui client (parent) and the
3	 * Node agent sidecar (child). The sidecar projects agent state; it never asks the client to decide outcomes.
4	 */
5	import type { ProviderRecoveryRecord, TurnResult } from "./core/turn.js";
6	import { redactSecrets, safeTerminal } from "./ui.js";
7	import { persistableEndpoint, scrubUrls } from "./core/endpoint_identity.js";
8	import type { ApprovalReview } from "./approval_review.js";
9	import type { SlashSpec } from "./slash/catalog.js";
10	import type { EvidenceStatus, ReceiptSection } from "./evidence.js";
11	import type { Catalog } from "./model_catalog.js";
12	
13	export const PROTOCOL_VERSION = 1;
14	export const MAX_TEXT_FIELD = 8000;
15	/**
16	 * Longest clipboard text `/paste` puts into the composer, and the limit of the `slash.result` composer field. It keeps
17	 * the escaped `slash.result` line under the TUI's 1 MiB protocol line cap.
18	 */
19	export const MAX_PASTE = 100_000;
20	export const MAX_SUMMARY = 160;
21	export const MAX_SLASH_OUTPUT = 32_000;
22	
23	export type ErrorCode = "BAD_REQUEST" | "BUSY" | "NO_PENDING_APPROVAL" | "NOT_FOUND" | "INTERNAL" | "NO_PROVIDER";
24	
25	/** Lines of a file diff shown in the transcript; the full diff is in the tool call's detail record. */
26	export const DIFF_PREVIEW_LINES = 40;
27	export const DIFF_PREVIEW_CHARS = 6000;
28	
29	/**
30	 * What became of operator steering sent while work was running. `queued`: held for the next step boundary.
31	 * `applied`: given to the agent (at a step boundary, or as a follow-up turn). `deferred`: the turn was finishing; it
32	 * starts a follow-up turn. `cancelled`: the turn ended first; `text` is returned to the operator. `rejected`: nothing
33	 * it could steer (a command is running); `text` is returned. `duplicate`: this id was already received. `held`: the
34	 * steering negates a requirement and waits for the operator's decision; the outcome follows as `applied` or `cancelled`.
35	 */
36	export type SteerStatus = "held" | "queued" | "applied" | "deferred" | "cancelled" | "rejected" | "duplicate";
37	
38	/** One entry of a resumed conversation: a message, a tool the agent called, or the last turn's outcome. */
39	export interface HistoryEntry {
40	  role: "user" | "assistant" | "steering" | "tool" | "outcome";
41	  text: string;
42	  tool?: string;
43	  heading?: string;
44	  turn?: TurnResult;
45	}
46	
47	export interface ModelSummary {
48	  summary: string;
49	  notes?: string;
50	}
51	
52	export type SidecarEvent =
53	  | { type: "hello"; protocol: number; pid: number; commands: Array<Pick<SlashSpec, "name" | "usage" | "summary">> }
54	  | {
55	      type: "session.state";
56	      workspace: string;
57	      workspace_name: string;
58	      model: string;
59	      mode: "auto" | "review" | "read-only";
60	      git: { branch: string; dirty: number } | null;
61	      busy: boolean;
62	      /** The id the session is saved under (shown so it can be resumed or referred to). */
63	      session?: string;
64	      /** The same facts the REPL /status reports (gate I-3). */
65	      read_only?: boolean;
66	      context_tokens?: number;
67	      context_limit?: number;
68	      endpoint_kind?: "local" | "cloud";
69	      posture?: {
70	        mode: "auto" | "review" | "read-only";
71	        sandbox: string;
72	        trusted: boolean;
73	      };
74	    }
75	  | { type: "assistant.delta"; turn_id: string; text: string }
76	  /** The provider's stream has sent nothing for `silent_secs` (`stalled`), or sent data again. */
77	  | { type: "stream.stall"; turn_id: string; stalled: boolean; silent_secs: number }
78	  /** What the running turn is doing; sent on every phase change, independent of model output. */
79	  | {
80	      type: "activity";
81	      turn_id: string;
82	      phase: string;
83	      step: number;
84	      segment: number;
85	      tool?: string;
86	      subject?: string;
87	      /** The turn's budget: total steps across segments, and the wall-clock limit in minutes (when continuation is on). */
88	      max_steps?: number;
89	      max_minutes?: number;
90	    }
91	  /** A file-edit tool changed a file: that operation's own diff (bounded preview; `evidence` opens the full one). */
92	  | {
93	      type: "file.diff";
94	      turn_id: string;
95	      call_id: string;
96	      evidence: string;
97	      path: string;
98	      kind: "added" | "modified" | "deleted";
99	      added: number;
100	      removed: number;
101	      preview: string;
102	      truncated: boolean;
103	      total_lines: number;
104	      /** Changed and context lines in the whole diff (what "N more lines" counts), and its hunks. */
105	      diff_lines: number;
106	      hunks: number;
107	      /** The complete diff on disk (redacted), kept for the session whatever the in-memory limits. */
108	      full_path?: string;
109	      note?: string;
110	    }
111	  | { type: "steer.ack"; id: string; status: SteerStatus; message: string; text?: string }
112	  | { type: "tool.start"; turn_id: string; call_id: string; tool: string; subject: string; evidence: string }
113	  | {
114	      type: "tool.end";
115	      turn_id: string;
116	      call_id: string;
117	      tool: string;
118	      success: boolean;
119	      summary: string;
120	      lines: number;
121	      evidence: string;
122	      /** Commands: the first lines of their output (stdout, then stderr), redacted, controls made visible. */
123	      preview?: string;
124	      exit_code?: number | null;
125	      duration_ms?: number;
126	      timed_out?: boolean;
127	      /** The operator declined the call at its approval prompt (never set for a policy refusal). The call did not run. */
128	      denied?: true;
129	    }
130	  | { type: "approval.request"; id: string; turn_id: string; tool: string; subject: string; preview: string; review: ApprovalReview }
131	  | { type: "checkpoint.choice.request"; id: string; turn_id: string; message: string }
132	  | { type: "turn.result"; turn_id: string; heading: string; line: string; turn: TurnResult; model_summary: ModelSummary | null; saved: boolean }
133	  | {
134	      type: "slash.result";
135	      id: string;
136	      command: string;
137	      success: boolean;
138	      output: string;
139	      /** "diff": colour unified-diff lines. */
140	      format?: "diff";
141	      /** Text for the client to put into the composer. */
142	      composer?: string;
143	      /** Text for the client to write to the terminal clipboard with OSC 52 (the client encodes it; at most OSC52_MAX_BYTES). */
144	      clipboard?: string;
145	      /** The command started a turn with this prompt; the turn's events follow under the same id. */
146	      prompt?: string;
147	    }
148	  /**
149	   * `key`: a later notice with the same key replaces this one on screen (a live status, not a log line).
150	   * `detail`: the raw cause, redacted, for the operator to inspect on request. Both are optional, so an older
151	   * client shows `text` as it always did.
152	   */
153	  | { type: "notice"; text: string; key?: string; detail?: string }
154	  /** A resumed session's recent conversation (user and assistant text only), oldest first; `total` counts all of it. */
155	  | { type: "history"; session: string; total: number; messages: HistoryEntry[] }
156	  | {
157	      type: "tool.detail";
158	      id: string;
159	      evidence: string;
160	      tool: string;
161	      subject: string;
162	      status: EvidenceStatus;
163	      args: string;
164	      output: string;
165	      duration_ms: number | null;
166	      /** Full unified diff of the change this call made, when it changed a file (at most MAX_DIFF_DETAIL chars). */
167	      diff?: string;
168	      /** Characters in the complete diff; more than `diff` holds when it was cut to the in-memory limit. */
169	      diff_chars?: number;
170	      /** The complete diff on disk. */
171	      diff_path?: string;
172	    }
173	  | { type: "receipt"; id: string; sections: ReceiptSection[] }
174	  | { type: "error"; id?: string; code: ErrorCode; message: string }
175	  /** Answer to models.list: providers (with connection source, never a credential), models, current and recent. */
176	  | ({ type: "models.catalog"; id: string } & Catalog)
177	  /** A sign-in needs the operator: open `url` (and type `user_code` for a device flow). */
178	  | { type: "provider.auth"; id: string; provider: string; url: string; user_code?: string; instructions: string }
179	  /** Outcome of provider.connect / provider.disconnect. */
180	  | { type: "provider.result"; id: string; provider: string; success: boolean; message: string }
181	  /** Outcome of model.select. */
182	  | { type: "model.result"; id: string; success: boolean; message: string };
183	
184	export type SidecarCommand =
185	  | { type: "prompt.submit"; id: string; text: string }
186	  /** Operator guidance for the work in progress (see SteerStatus). */
187	  | { type: "steer"; id: string; text: string }
188	  | { type: "cancel" }
189	  | { type: "approve"; id: string; always: boolean }
190	  | { type: "deny"; id: string }
191	  /**
192	   * VC-9: the operator's decision on a question a turn ended BLOCKED / NEEDS_INPUT with (`turn.needsInput.id`), for a
193	   * client with no live approval prompt. It is recorded now and applied when the next turn reaches that decision.
194	   */
195	  | { type: "answer"; id: string; question: string; option: "approve" | "decline" }
196	  | { type: "checkpoint.choice"; id: string; choice: "read_only" | "without_checkpoint" | "retry" | "allow_sensitive" | "cancel" | "other" }
197	  | { type: "slash"; id: string; command: string; args: string }
198	  | { type: "tool.detail"; id: string; evidence: string }
199	  | { type: "receipt"; id: string }
200	  | { type: "models.list"; id: string }
201	  | { type: "model.select"; id: string; provider: string; model: string }
202	  /** `key` only for method "api-key"; it is never echoed back or logged. */
203	  | { type: "provider.connect"; id: string; provider: string; method: string; key?: string; endpoint?: string }
204	  | { type: "provider.cancel"; id: string }
205	  /** Clear a completed local endpoint setup associated with this exact provider.connect request. */
206	  | { type: "provider.local-cancel"; id: string }
207	  | { type: "provider.disconnect"; id: string; provider: string }
208	  | { type: "shutdown" };
209	
210	export class ProtocolError extends Error {
211	  constructor(message: string, public readonly id?: string) {
212	    super(message);
213	    this.name = "ProtocolError";
214	  }
215	}
216	
217	const LONE_SURROGATE = /[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/g;
218	
219	/** Truncation can split a surrogate pair; a lone surrogate would serialize as JSON the client cannot decode. */
220	export function encodeEvent(event: SidecarEvent): string {
221	  const wellFormed = (_key: string, value: unknown) => (typeof value === "string" ? value.replace(LONE_SURROGATE, "\uFFFD") : value);
222	  return JSON.stringify({ v: PROTOCOL_VERSION, ...event }, wellFormed) + "\n";
223	}
224	
225	export function parseCommand(line: string): SidecarCommand {
226	  let raw: unknown;
227	  try {
228	    raw = JSON.parse(line);
229	  } catch {
230	    throw new ProtocolError("line is not valid JSON");
231	  }
232	  if (!raw || typeof raw !== "object" || Array.isArray(raw)) throw new ProtocolError("message must be a JSON object");
233	  const msg = raw as Record<string, unknown>;
234	  const id = typeof msg.id === "string" && msg.id ? msg.id : undefined;
235	  if (msg.v !== PROTOCOL_VERSION) throw new ProtocolError(`unsupported protocol version: ${String(msg.v)}`, id);
236	  const requireId = (type: string): string => {
237	    if (!id) throw new ProtocolError(`${type} requires id`);
238	    return id;
239	  };
240	  switch (msg.type) {
241	    case "prompt.submit": {
242	      const requestId = requireId("prompt.submit");
243	      const text = msg.text;
244	      if (typeof text !== "string" || !text.trim()) throw new ProtocolError("prompt.submit requires non-empty text", requestId);
245	      return { type: "prompt.submit", id: requestId, text };
246	    }
247	    case "steer": {
248	      const requestId = requireId("steer");
249	      const text = msg.text;
250	      if (typeof text !== "string" || !text.trim()) throw new ProtocolError("steer requires non-empty text", requestId);
251	      return { type: "steer", id: requestId, text };
252	    }
253	    case "cancel":
254	      return { type: "cancel" };
255	    case "approve":
256	      return { type: "approve", id: requireId("approve"), always: msg.always === true };
257	    case "deny":
258	      return { type: "deny", id: requireId("deny") };
259	    case "answer": {
260	      const requestId = requireId("answer");
261	      if (typeof msg.question !== "string" || !/^[0-9a-f]{12}$/.test(msg.question)) throw new ProtocolError("answer requires question: the 12-character needsInput.id", requestId);
262	      if (msg.option !== "approve" && msg.option !== "decline") throw new ProtocolError("answer requires option: approve or decline", requestId);
263	      return { type: "answer", id: requestId, question: msg.question, option: msg.option };
264	    }
265	    case "checkpoint.choice": {
266	      const requestId = requireId("checkpoint.choice");
267	      const choices = ["read_only", "without_checkpoint", "retry", "allow_sensitive", "cancel", "other"] as const;
268	      if (!choices.includes(msg.choice as typeof choices[number])) throw new ProtocolError("checkpoint.choice requires a supported choice", requestId);
269	      return { type: "checkpoint.choice", id: requestId, choice: msg.choice as typeof choices[number] };
270	    }
271	    case "slash": {
272	      const requestId = requireId("slash");
273	      const command = msg.command;
274	      if (typeof command !== "string" || !command.trim()) throw new ProtocolError("slash requires command", requestId);
275	      return { type: "slash", id: requestId, command, args: typeof msg.args === "string" ? msg.args : "" };
276	    }
277	    case "tool.detail": {
278	      const requestId = requireId("tool.detail");
279	      const evidence = msg.evidence;
280	      if (typeof evidence !== "string" || !evidence) throw new ProtocolError("tool.detail requires evidence", requestId);
281	      return { type: "tool.detail", id: requestId, evidence };
282	    }
283	    case "receipt":
284	      return { type: "receipt", id: requireId("receipt") };
285	    case "models.list":
286	      return { type: "models.list", id: requireId("models.list") };
287	    case "model.select": {
288	      const requestId = requireId("model.select");
289	      if (typeof msg.provider !== "string" || !msg.provider || typeof msg.model !== "string" || !msg.model.trim()) {
290	        throw new ProtocolError("model.select requires provider and model", requestId);
291	      }
292	      return { type: "model.select", id: requestId, provider: msg.provider, model: msg.model };
293	    }
294	    case "provider.connect": {
295	      const requestId = requireId("provider.connect");
296	      if (typeof msg.provider !== "string" || !msg.provider || typeof msg.method !== "string" || !msg.method) {
297	        throw new ProtocolError("provider.connect requires provider and method", requestId);
298	      }
299	      if (msg.key !== undefined && typeof msg.key !== "string") throw new ProtocolError("provider.connect key must be a string", requestId);
300	      if (msg.endpoint !== undefined && (typeof msg.endpoint !== "string" || !msg.endpoint || msg.endpoint.length > 2048 || /[\r\n\0]/.test(msg.endpoint))) {
301	        throw new ProtocolError("provider.connect endpoint must be a valid single-line URL", requestId);
302	      }
303	      return {
304	        type: "provider.connect", id: requestId, provider: msg.provider, method: msg.method,
305	        ...(typeof msg.key === "string" ? { key: msg.key } : {}),
306	        ...(typeof msg.endpoint === "string" ? { endpoint: msg.endpoint } : {}),
307	      };
308	    }
309	    case "provider.cancel":
310	      return { type: "provider.cancel", id: requireId("provider.cancel") };
311	    case "provider.local-cancel":
312	      return { type: "provider.local-cancel", id: requireId("provider.local-cancel") };
313	    case "provider.disconnect": {
314	      const requestId = requireId("provider.disconnect");
315	      if (typeof msg.provider !== "string" || !msg.provider) throw new ProtocolError("provider.disconnect requires provider", requestId);
316	      return { type: "provider.disconnect", id: requestId, provider: msg.provider };
317	    }
318	    case "shutdown":
319	      return { type: "shutdown" };
320	    default:
321	      throw new ProtocolError(`unknown message type: ${String(msg.type)}`, id);
322	  }
323	}
324	
325	export function capText(text: string, max: number = MAX_TEXT_FIELD): string {
326	  if (text.length <= max) return text;
327	  return `${text.slice(0, max)}…[truncated ${text.length - max} chars]`;
328	}
329	
330	/** CSI sequences, OSC sequences (BEL or ST terminated), then the remaining two-character escapes. */
331	const TERMINAL_ESCAPE = /\x1b\[[0-9;?]*[ -/]*[@-~]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)|\x1b[ -/]*[0-~]/g;
332	
333	export function stripEscapes(text: string): string {
334	  return text.replace(TERMINAL_ESCAPE, "");
335	}
336	
337	/** Secrets redacted from text with terminal escape sequences removed: the shared first step of every operator-facing one-line projection. */
338	export function redactPlain(text: string): string {
339	  return redactSecrets(stripEscapes(text));
340	}
341	
342	/** Operator-supplied text as shown to an operator or written to a record: escapes and control characters gone, secrets redacted, one line, capped. */
343	export function safeOperatorText(text: string, max = 300): string {
344	  return redactSecrets(stripEscapes(String(text)).replace(/[\x00-\x1f\x7f-\x9f]+/g, " ")).replace(/\s+/g, " ").trim().slice(0, max);
345	}
346	
347	export function toolSubject(args: Record<string, any>, tool?: string): string {
348	  if (tool === "steering_conflict" && Array.isArray(args.negates)) {
349	    const ids = args.negates.map((n: any) => safeOperatorText(String(n?.id ?? ""), 12)).join(", ");
350	    return safeOperatorText(`steering ${args.steering} negates ${ids}: ${args.text}`, 200);
351	  }
352	  const subject = args.path ?? args.file_path ?? args.command ?? args.url ?? args.query ?? args.name ?? "";
353	  return redactPlain(String(subject)).replace(/\s+/g, " ").trim().slice(0, 200);
354	}
355	
356	/** Copy of a turn with secrets redacted from its free-text fields; enums, counts, ids and hashes are left as-is. */
357	export function projectTurn(turn: TurnResult): TurnResult {
358	  const redactOptional = (text: string | undefined) => (text === undefined ? undefined : redactSecrets(text));
359	  return {
360	    ...turn,
361	    detail: redactOptional(turn.detail),
362	    verification: turn.verification ? { ...turn.verification, command: redactOptional(turn.verification.command) } : null,
363	    interruption: turn.interruption ? { ...turn.interruption, outstandingTool: redactOptional(turn.interruption.outstandingTool) } : null,
364	    inferenceFailure: turn.inferenceFailure ? { ...turn.inferenceFailure, message: redactSecrets(turn.inferenceFailure.message) } : null,
365	    ...(turn.convergence
366	      ? {
367	          convergence: {
368	            ...turn.convergence,
369	            evidence: redactSecrets(turn.convergence.evidence),
370	            attempts: turn.convergence.attempts.map((a) => ({
371	              ...a,
372	              command: redactSecrets(a.command),
373	              ...(a.failedCheck ? { failedCheck: redactSecrets(a.failedCheck) } : {}),
374	              ...(a.failingTests ? { failingTests: a.failingTests.map((t) => redactSecrets(t)) } : {}),
375	            })),
376	          },
377	        }
378	      : {}),
379	    ...(turn.turnEvidence
380	      ? { turnEvidence: { ...turn.turnEvidence, verifierRuns: turn.turnEvidence.verifierRuns.map((r) => ({ ...r, command: redactSecrets(r.command) })) } }
381	      : {}),
382	    ...(turn.providerRecovery
383	      ? {
384	          providerRecovery: turn.providerRecovery.map((r) => ({
385	            ...r,
386	            reason: redactOptional(r.reason),
387	            submissions: r.submissions.map((s) => ({ ...s, message: redactSecrets(s.message) })),
388	          })),
389	        }
390	      : {}),
391	  };
392	}
393	
394	/** The notice key of every provider-wait line: one live row that each transition replaces. */
395	export const PROVIDER_STATUS_KEY = "provider.recovery";
396	export const STARTUP_PROVIDER_KEY = "provider.startup";
397	
398	export interface StatusNotice {
399	  text: string;
400	  key: string;
401	  /** The raw cause (redacted); never part of `text`. */
402	  detail?: string;
403	}
404	
405	/** What went wrong, in words an operator can act on. */
406	function providerProblemWords(record: ProviderRecoveryRecord): string {
407	  const last = record.submissions[record.submissions.length - 1];
408	  const status = last?.httpStatus;
409	  if (record.condition === "AUTH_FAILURE" || status === 401 || status === 403) return "the provider rejected the credentials";
410	  if (record.condition === "QUOTA_EXHAUSTED" || status === 402) return "the provider account is out of quota";
411	  if (record.condition === "RATE_LIMITED" || status === 429) return "the provider is rate limiting requests";
412	  if (record.condition === "OVERLOADED" || status === 503 || status === 529) return "the provider is overloaded";
413	  if (record.condition === "DRAINING") return "the provider is restarting";
414	  if (last?.kind === "timeout") return "the provider did not answer in time";
415	  if (last?.kind === "network_error" || record.condition === "TEMPORARILY_UNAVAILABLE") return "the provider cannot be reached";
416	  return "the provider returned an error";
417	}
418	
419	function minutesWords(ms: number): string {
420	  const minutes = Math.round(ms / 60_000);
421	  return minutes < 1 ? "under a minute" : `about ${minutes} min`;
422	}
423	
424	function rawProviderCause(record: ProviderRecoveryRecord): string {
425	  const last = record.submissions[record.submissions.length - 1];
426	  const parts = [
427	    `condition ${record.condition}${last?.httpStatus ? `, HTTP ${last.httpStatus}` : ""}${last ? `, ${last.kind}, execution ${last.execution}` : ""}`,
428	    last?.message,
429	    record.reason ? `recovery: ${record.reason}` : undefined,
430	    last?.requestId ? `request ${last.requestId}` : undefined,
431	  ];
432	  return redactSecrets(scrubUrls(parts.filter(Boolean).join("\n")));
433	}
434	
435	/**
436	 * The provider-wait status line for one recovery transition (PROBING produces none). Every transition carries the
437	 * same `key`, so the client shows one row that changes instead of a line per attempt (D-06).
438	 */
439	export function providerRecoveryStatus(record: ProviderRecoveryRecord, discardedPartialOutput: boolean): StatusNotice | undefined {
440	  if (record.state === "PROBING") return undefined;
441	  const detail = rawProviderCause(record);
442	  const where = record.endpoint ? ` at ${persistableEndpoint(record.endpoint)}` : "";
443	  const problem = providerProblemWords(record);
444	  switch (record.state) {
445	    case "WAITING": {
446	      const secs = record.nextAttemptAt ? Math.max(0, Math.round((Date.parse(record.nextAttemptAt) - Date.parse(record.updatedAt)) / 1000)) : 0;
447	      const left = minutesWords(Math.max(0, record.policy.deadlineMs - record.waitedMs));
448	      const discarded = discardedPartialOutput ? " The partial response was discarded." : "";
449	      const text = `Waiting for the model provider${where}: ${problem}. Retry ${record.submissions.length}, next attempt in ${secs}s; gives up in ${left}. Your work is kept. /details shows the raw error; esc cancels.${discarded}`;
450	      return { text: redactSecrets(text), key: PROVIDER_STATUS_KEY, detail };
451	    }
452	    case "RESUMED":
453	      return { text: `The model provider recovered after ${Math.round(record.waitedMs / 1000)}s; step ${record.step} resumed.`, key: PROVIDER_STATUS_KEY, detail: `Recovered; the earlier error was:\n${detail}` };
454	    case "CANCELLED":
455	      return { text: "Stopped waiting for the model provider.", key: PROVIDER_STATUS_KEY, detail };
456	    default:
457	      return {
458	        text: redactSecrets(`Nexus stopped retrying the model provider${where}: ${problem}. Check the connection or use /connect, then send your message again. /details shows the raw error.`),
459	        key: PROVIDER_STATUS_KEY,
460	        detail,
461	      };
462	  }
463	}
464	
465	/** The answer to a prompt sent while the provider is still down: short, because the start-up notice already gave the steps. */
466	export function noProviderRefusal(problem: { endpoint: string; endpoints?: string[]; nothingThere?: boolean }): string {
467	  const named = problem.endpoints?.join(", ") ?? problem.endpoint;
468	  const why = problem.nothingThere === false ? `could not connect to ${named}` : `nothing answers at ${named}`;
469	  return redactSecrets(`Not sent: no model is connected (${why}). Use /connect or start a local model server, then send it again.`);
470	}
471	
472	/** First run with nothing to talk to: what is missing, what to do next, where to read more. The raw cause goes in `detail`. */
473	export function noProviderNotice(problem: { kind: "unreachable" | "rejected"; endpoint: string; endpoints?: string[]; detail: string; blocking?: boolean; nothingThere?: boolean }): StatusNotice {
474	  if (problem.kind === "rejected" || problem.blocking === false) {
475	    // Only a warning: the start-up check can be refused where chat is not (a token not yet refreshed, a key limited to chat).
476	    // With several endpoints that failed, each is named and the wording does not say how each failed (the detail does).
477	    const many = (problem.endpoints?.length ?? 0) > 1;
478	    const verb = many ? "did not pass" : problem.kind === "rejected" ? "rejected the credentials on" : "did not answer";
479	    return {
480	      text: redactSecrets(
481	        `${many ? problem.endpoints!.join(", ") : problem.endpoint} ${verb} the start-up check. Nexus will still try your messages; ` +
482	          `if they fail, type /connect to sign in again or check the API key and the server. \`nexus doctor\` checks the setup.`,
483	      ),
484	      key: STARTUP_PROVIDER_KEY,
485	      detail: redactSecrets(problem.detail),
486	    };
487	  }
488	  const named = problem.endpoints?.join(", ") ?? problem.endpoint;
489	  const missing = problem.nothingThere === false ? `No model is connected: Nexus could not connect to ${named}.` : `No model is connected: nothing answers at ${named}.`;
490	  const text =
491	    `${missing} Next: type /connect to sign in or add an API key, or start a local model server (LM Studio, Ollama, llama.cpp) ` +
492	    `and send your message again. \`nexus doctor\` checks the setup; docs/CLOUD_PROVIDERS.md lists providers.`;
493	  return { text: redactSecrets(text), key: STARTUP_PROVIDER_KEY, detail: redactSecrets(problem.detail) };
494	}
495	
496	/** Lines of a command's output carried in `tool.end` for the transcript preview. */
497	export const TOOL_PREVIEW_LINES = 8;
498	
499	export interface ToolSummary {
500	  summary: string;
501	  lines: number;
502	  preview?: string;
503	  exit_code?: number | null;
504	  duration_ms?: number;
505	  timed_out?: boolean;
506	}
507	
508	/**
509	 * What the transcript shows for a finished tool. A command's JSON result (`stdout`, `stderr`, `exit_code`) becomes a
510	 * real summary (`exit 0 · 122 lines`, or `no output`), the count of its output lines and a bounded preview of them;
511	 * other tools keep the first line of their output (or error) as the summary.
512	 */
513	export function toolSummary(success: boolean, output: string, error?: string): ToolSummary {
514	  const command = commandResult(output);
515	  if (command) {
516	    const body = [command.stdout.trimEnd(), command.stderr.trimEnd()].filter(Boolean).join("\n");
517	    const rows = body ? body.split(/\r?\n/) : [];
518	    const exit = command.timed_out ? "timed out" : command.exit_code === null ? "no exit code" : `exit ${command.exit_code}`;
519	    const failure = success ? "" : (error ?? "").split(/\r?\n/).find((line) => line.trim())?.trim() ?? "";
520	    const summary = failure && !failure.startsWith("{") ? failure : `${exit} · ${rows.length ? `${rows.length} line${rows.length === 1 ? "" : "s"}` : "no output"}`;
521	    return {
522	      summary: redactPlain(summary).replace(/\s+/g, " ").slice(0, MAX_SUMMARY),
523	      lines: rows.length,
524	      preview: (rows.length > TOOL_PREVIEW_LINES ? rows.slice(-TOOL_PREVIEW_LINES) : rows).map((row) => safeTerminal(row).slice(0, 400)).join("\n"),
525	      exit_code: command.exit_code,
526	      ...(command.duration_ms !== undefined ? { duration_ms: command.duration_ms } : {}),
527	      ...(command.timed_out ? { timed_out: true } : {}),
528	    };
529	  }
530	  const text = redactPlain(success ? output || "" : error || output || "").trim();
531	  const first = text.split(/\r?\n/).find((line) => line.trim())?.trim() ?? (success ? "Completed" : "Tool failed");
532	  return { summary: first.replace(/\s+/g, " ").slice(0, MAX_SUMMARY), lines: text ? text.split(/\r?\n/).length : 0 };
533	}
534	
535	/** The structured result of a shell command tool, when `output` is one. */
536	function commandResult(output: string): { stdout: string; stderr: string; exit_code: number | null; duration_ms?: number; timed_out?: boolean } | undefined {
537	  if (!output || output.trimStart()[0] !== "{") return undefined;
538	  try {
539	    const parsed = JSON.parse(output);
540	    if (parsed && typeof parsed === "object" && typeof parsed.stdout === "string" && "exit_code" in parsed) {
541	      return {
542	        stdout: parsed.stdout,
543	        stderr: typeof parsed.stderr === "string" ? parsed.stderr : "",
544	        exit_code: typeof parsed.exit_code === "number" ? parsed.exit_code : null,
545	        ...(typeof parsed.duration_ms === "number" ? { duration_ms: parsed.duration_ms } : {}),
546	        ...(parsed.timed_out === true ? { timed_out: true } : {}),
547	      };
548	    }
549	  } catch {}
550	  return undefined;
551	}
552

