283	      if (!controller.signal.aborted) this.emit({ type: "error", id, code: "INTERNAL", message: errorText(err) });
284	    } finally {
285	      if (this.modelLists.get(id) === controller) this.modelLists.delete(id);
286	    }
287	  }
